plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
}

group = "net.olamaelcu"

android {
    namespace = "net.olamaelcu.livtet.branding"
    compileSdk = 35

    defaultConfig {
        minSdk = 24
    }

    // Per-store flavor tints. Consumers (e.g. mobile/android/app) must
    // declare the same `store` flavor dimension with matching flavor
    // names (`playstore`, `fdroid`, `generic`) so AGP picks the right
    // variant per consumer build. The per-flavor resources live in
    // `src/main/res/<flavor>/` and are generated by `branding/generate.ts`
    // from `branding/tokens.json#color.brand.flavor` — see ANDROID_STORE_FLAVORS
    // in `scripts/lib.ts` for the canonical list. Adding a new flavor
    // here without updating `tokens.json` makes the generator fail loudly.
    flavorDimensions += "store"
    productFlavors {
        create("playstore") { dimension = "store" }
        create("fdroid")    { dimension = "store" }
        create("generic")   { dimension = "store" }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
    }
}

dependencies {
    implementation(platform("androidx.compose:compose-bom:2026.03.00"))
    implementation("androidx.compose.material3:material3")
    implementation("androidx.compose.ui:ui")
}
